param([switch]$Release)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$csc=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe';$build=Join-Path $root build;$dist=Join-Path $root dist;New-Item -ItemType Directory -Force $build,$dist|Out-Null
$icon=Join-Path $build 'empty-folder-radar.ico';& "$PSScriptRoot\New-AppIcon.ps1" -OutputPath $icon
$src=Get-ChildItem "$root\src" -Filter *.cs|% FullName;&$csc /nologo /target:winexe /optimize+ /platform:anycpu /win32manifest:"$root\app.manifest" /win32icon:"$icon" /r:System.dll /r:System.Core.dll /r:System.Drawing.dll /r:System.Windows.Forms.dll /r:Microsoft.VisualBasic.dll /out:"$dist\empty-folder-radar.exe" $src;if($LASTEXITCODE-ne0){throw 'Build failed'}
$tests=@("$root\src\EmptyFolderItem.cs","$root\src\ScanResult.cs","$root\src\EmptyFolderScanner.cs","$root\src\SafetyGuard.cs","$root\tests\ScannerTests.cs");&$csc /nologo /target:exe /optimize+ /r:System.dll /r:System.Core.dll /out:"$build\tests.exe" $tests;if($LASTEXITCODE-ne0){throw 'Test build failed'};&"$build\tests.exe";if($LASTEXITCODE-ne0){throw 'Tests failed'}
if($Release){$stage=Join-Path $build 'empty-folder-radar-v0.1.1-windows-x64';if(Test-Path $stage){Remove-Item $stage -Recurse -Force};New-Item -ItemType Directory $stage|Out-Null;Copy-Item "$dist\empty-folder-radar.exe","$root\README.md","$root\LICENSE" $stage;$zip=Join-Path $dist 'empty-folder-radar-v0.1.1-windows-x64.zip';if(Test-Path $zip){Remove-Item $zip -Force};Compress-Archive "$stage\*" $zip;$hash=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLowerInvariant();Set-Content "$zip.sha256" "$hash  $(Split-Path -Leaf $zip)" -Encoding ascii}
Write-Host "Built: $dist\empty-folder-radar.exe"
